-- Schema-only snapshot for local destructive-operation tests. No production rows.
create table public."activities" (
"id" uuid default gen_random_uuid() not null,
"code" text not null,
"display_name" text not null,
"category" text,
"external_link" text,
"teacher_comment" text,
"active" boolean default true not null,
"content" jsonb default '{}'::jsonb not null
);
create table public."activity_categories" (
"id" bigint generated by default as identity not null,
"name" text not null
);
create table public."announcement_reads" (
"id" uuid default gen_random_uuid() not null,
"announcement_id" uuid not null,
"student_id" uuid not null,
"seen_at" timestamp with time zone default now() not null
);
create table public."announcements" (
"id" uuid default gen_random_uuid() not null,
"title" text not null,
"message" text not null,
"image_link" text,
"target_type" text default 'all'::text not null,
"target_list" jsonb default '[]'::jsonb not null,
"display_limit" integer,
"theme" text,
"active" boolean default true not null,
"created_at" timestamp with time zone default now() not null,
"teacher_id" uuid
);
create table public."annual_plans" (
"id" uuid default gen_random_uuid() not null,
"plan_code" text not null,
"title" text,
"total_weeks" integer default 0 not null,
"plan_data" jsonb default '[]'::jsonb not null,
"active" boolean default true not null
);
create table public."assignment_status" (
"assignment_id" bigint not null,
"student_id" uuid not null,
"done_at" timestamp with time zone default now() not null,
"score" integer,
"stars" integer
);
create table public."assignments" (
"id" bigint generated by default as identity not null,
"teacher_id" uuid,
"class_no" integer not null,
"branch" text default ''::text not null,
"kind" text not null,
"title" text not null,
"payload" jsonb default '{}'::jsonb not null,
"due_date" date,
"note" text,
"active" boolean default true not null,
"created_at" timestamp with time zone default now() not null
);
create table public."audit_logs" (
"id" uuid default gen_random_uuid() not null,
"actor_role" text,
"actor_id" uuid,
"operation" text,
"target" text,
"payload" jsonb default '{}'::jsonb not null,
"created_at" timestamp with time zone default now() not null
);
create table public."badges" (
"id" bigint generated by default as identity not null,
"student_name" text,
"name" text not null,
"required_points" numeric default 0,
"emoji" text default '🏅'::text
);
create table public."chat_messages" (
"id" uuid default gen_random_uuid() not null,
"student_id" uuid,
"sender_role" text not null,
"message" text not null,
"read_at" timestamp with time zone,
"created_at" timestamp with time zone default now() not null
);
